window.NEURO = {"questions": [{"id": "Q001", "ref": "slide-3", "page": 3, "topic": "Arterial anatomy", "stem": "Which arteries normally unite to form the basilar artery?", "options": [{"text": "Middle cerebral arteries", "why": "These are carotid-system branches."}, {"text": "Posterior communicating arteries", "why": "These connect carotid circulation to posterior cerebral arteries."}, {"text": "Anterior cerebral arteries", "why": "They are connected by ACOM, not joined as basilar."}, {"text": "Internal carotid arteries", "why": "These supply anterior circulation rather than uniting as basilar."}, {"text": "Vertebral arteries", "why": "The paired vertebral arteries join to form the basilar trunk."}], "answer": 4}, {"id": "Q002", "ref": "slide-3", "page": 3, "topic": "Arterial anatomy", "stem": "Which artery usually arises from a vertebral artery rather than the basilar artery?", "options": [{"text": "AICA", "why": "This is usually a basilar branch."}, {"text": "PICA", "why": "Posterior inferior cerebellar artery is classically a vertebral branch."}, {"text": "PCA", "why": "The basilar usually terminates as the paired PCAs."}, {"text": "SCA", "why": "This is usually a distal basilar branch."}, {"text": "Pontine perforators", "why": "These arise from basilar circulation."}], "answer": 1}, {"id": "Q003", "ref": "slide-3", "page": 3, "topic": "Arterial anatomy", "stem": "Which vessel connects the anterior cerebral arteries?", "options": [{"text": "Anterior spinal artery", "why": "ASA supplies spinal and medial medullary territories."}, {"text": "Superior cerebellar artery", "why": "SCA supplies posterior fossa territories rather than joining ACAs."}, {"text": "Middle meningeal artery", "why": "This mainly supplies dura."}, {"text": "Posterior communicating artery", "why": "PCOM connects internal carotid and PCA circulation."}, {"text": "Anterior communicating artery", "why": "ACOM links the two ACAs."}], "answer": 4}, {"id": "Q004", "ref": "slide-3", "page": 3, "topic": "Arterial anatomy", "stem": "Which relationship correctly describes the posterior communicating artery?", "options": [{"text": "It terminates as ACA and MCA", "why": "Internal carotid supplies those terminal branches."}, {"text": "It joins the vertebral arteries to form basilar", "why": "Vertebral arteries themselves unite."}, {"text": "It is the main artery entering the parotid gland", "why": "This is not its intracranial role."}, {"text": "It is a venous sinus", "why": "It is an artery."}, {"text": "It links internal carotid circulation to PCA circulation", "why": "PCOM is a carotid-posterior connection in the circle of Willis."}], "answer": 4}, {"id": "Q005", "ref": "slide-4", "page": 4, "topic": "Supply by level", "stem": "Which arterial combination best matches major midbrain supply in the lecture?", "options": [{"text": "Facial and lingual arteries", "why": "These are external carotid head/neck branches."}, {"text": "PICA and ASA alone", "why": "These are strongly associated with medullary territories."}, {"text": "PCA and SCA branches", "why": "These contribute to midbrain territories."}, {"text": "ACA and MCA alone", "why": "These mainly supply cerebral rather than major midbrain territories."}, {"text": "Only the superior sagittal sinus", "why": "This is venous drainage rather than arterial supply."}], "answer": 2}, {"id": "Q006", "ref": "slide-4", "page": 4, "topic": "Supply by level", "stem": "Which combination best matches pontine supply?", "options": [{"text": "ACA and ACOM only", "why": "These are anterior cerebral circulation structures."}, {"text": "Central retinal and ophthalmic arteries", "why": "These supply ocular structures."}, {"text": "PICA and ASA as the only pontine vessels", "why": "These are more characteristic of medullary supply."}, {"text": "Basilar pontine branches with AICA and SCA contributions", "why": "Supply varies between medial and lateral levels/territories."}, {"text": "Inferior mesenteric artery", "why": "This supplies hindgut, not brainstem."}], "answer": 3}, {"id": "Q007", "ref": "slide-4", "page": 4, "topic": "Supply by level", "stem": "Which group supplies major medullary territories?", "options": [{"text": "Coronary arteries", "why": "These supply myocardium."}, {"text": "MCA, ACA, and ACOM only", "why": "These chiefly belong to anterior cerebral circulation."}, {"text": "Vertebral, PICA, and ASA branches", "why": "These are the lecture's key medullary vessels."}, {"text": "SCA and ophthalmic alone", "why": "This does not describe the major medullary group."}, {"text": "External carotid and maxillary alone", "why": "These are not the major intraparenchymal medullary supply."}], "answer": 2}, {"id": "Q008", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "A motor nucleus supplies somite-related extraocular skeletal muscle. Which functional component is it?", "options": [{"text": "GSE", "why": "III/IV/VI ocular motor output is general somatic efferent."}, {"text": "GVE", "why": "This is autonomic efferent output."}, {"text": "GVA", "why": "This is visceral sensory input."}, {"text": "SVE", "why": "This is branchial motor output."}, {"text": "SVA", "why": "This is taste/smell sensory input."}], "answer": 0}, {"id": "Q009", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Which group contains only GSE nuclei represented on the chart?", "options": [{"text": "Motor V, facial VII, and ambiguus", "why": "These are branchial motor/SVE."}, {"text": "Principal and spinal trigeminal nuclei", "why": "These are GSA sensory structures."}, {"text": "EW and salivatory nuclei", "why": "These are GVE."}, {"text": "III, IV, VI, and XII motor nuclei", "why": "These supply extraocular and tongue skeletal muscles."}, {"text": "Solitary and cochlear nuclei", "why": "These are sensory."}], "answer": 3}, {"id": "Q010", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Which motor output is classified as SVE/branchial motor?", "options": [{"text": "Muscles of mastication through motor V", "why": "These are pharyngeal-arch-derived skeletal muscles."}, {"text": "Taste through VII", "why": "This is SVA sensory."}, {"text": "Body vibration through medial lemniscus", "why": "This is ascending sensory input, not branchial motor output."}, {"text": "Sphincter pupillae through EW", "why": "This is GVE parasympathetic output."}, {"text": "Lateral rectus through VI", "why": "This is GSE."}], "answer": 0}, {"id": "Q011", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Which nucleus provides the preganglionic parasympathetic output associated with CN III?", "options": [{"text": "Facial motor nucleus", "why": "This supplies facial-expression muscles."}, {"text": "Cochlear nucleus", "why": "This processes hearing."}, {"text": "Principal V nucleus", "why": "This processes face touch/vibration."}, {"text": "Edinger-Westphal", "why": "EW fibers travel through III toward the ciliary ganglion."}, {"text": "Oculomotor GSE nucleus alone", "why": "This supplies skeletal eye muscles, not the parasympathetic origin."}], "answer": 3}, {"id": "Q012", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Which pairing is correct for the salivatory nuclei?", "options": [{"text": "Superior — IX; inferior — VII", "why": "This reverses the classic pairing."}, {"text": "Superior — VII; inferior — IX", "why": "Superior salivatory-related output serves VII glandular pathways; inferior serves IX/parotid."}, {"text": "Both — XII", "why": "XII is tongue motor."}, {"text": "Both — VIII", "why": "VIII is special sensory."}, {"text": "Superior — II; inferior — I", "why": "These are forebrain-associated sensory nerves rather than salivatory pathways."}], "answer": 1}, {"id": "Q013", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Which nucleus chiefly supplies much of vagal parasympathetic output to thoracoabdominal organs?", "options": [{"text": "Inferior colliculus", "why": "This is an auditory midbrain structure."}, {"text": "Abducens nucleus", "why": "This coordinates horizontal gaze."}, {"text": "Dorsal motor nucleus of X", "why": "It contains GVE preganglionic neurons; cardiac vagal circuitry also includes ambiguus-related neurons."}, {"text": "Spinal V nucleus", "why": "This is somatic sensory."}, {"text": "Hypoglossal nucleus", "why": "This is tongue GSE motor."}], "answer": 2}, {"id": "Q014", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Taste and visceral afferents carried by VII, IX, and X share which central sensory nucleus?", "options": [{"text": "Spinal accessory nucleus", "why": "This supplies SCM/trapezius through spinal XI."}, {"text": "Nucleus ambiguus", "why": "This is branchial motor."}, {"text": "Solitary nucleus", "why": "Rostral regions chiefly handle taste and caudal regions visceral information."}, {"text": "Facial motor nucleus", "why": "This is SVE motor."}, {"text": "Edinger-Westphal nucleus", "why": "This is parasympathetic motor."}], "answer": 2}, {"id": "Q015", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Which trigeminal sensory nucleus is associated with jaw-related proprioception?", "options": [{"text": "Spinal V", "why": "This chiefly handles pain/temperature."}, {"text": "Superior salivatory", "why": "This supplies VII parasympathetic output."}, {"text": "Principal sensory V", "why": "This chiefly handles fine touch/vibration."}, {"text": "Motor V", "why": "This supplies branchial motor output."}, {"text": "Mesencephalic nucleus of V", "why": "It unusually contains primary sensory somata within the CNS."}], "answer": 4}, {"id": "Q016", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Which nucleus processes facial fine touch and vibration?", "options": [{"text": "Spinal V nucleus", "why": "This chiefly processes pain/temperature."}, {"text": "Hypoglossal nucleus", "why": "This is tongue motor."}, {"text": "Solitary nucleus", "why": "This processes taste/visceral afferents."}, {"text": "Cochlear nucleus", "why": "This processes hearing."}, {"text": "Principal sensory nucleus of V", "why": "This is the major pontine discriminative facial sensory relay."}], "answer": 4}, {"id": "Q017", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "The spinal trigeminal nucleus receives small somatic sensory contributions from which nerves in addition to V?", "options": [{"text": "I and II exclusively", "why": "These special sensory systems do not use the spinal V relay."}, {"text": "Only spinal phrenic motor fibers", "why": "These are not the cranial somatic sensory contributions."}, {"text": "XI and XII as the main taste input", "why": "These nerves are principally motor."}, {"text": "III, IV, and VI as their major motor output", "why": "These are ocular motor pathways, not the GSA contributions asked for."}, {"text": "VII, IX, and X", "why": "Their small GSA territories can project to the spinal trigeminal system."}], "answer": 4}, {"id": "Q018", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Which nuclei are SSA sensory structures spanning the pontomedullary region?", "options": [{"text": "Superior and inferior salivatory nuclei", "why": "These are GVE."}, {"text": "Hypoglossal and abducens nuclei", "why": "These are GSE motor."}, {"text": "Vestibular and cochlear nuclei", "why": "VIII conveys hearing and balance."}, {"text": "EW and dorsal motor X", "why": "These are GVE motor."}, {"text": "Facial and motor V nuclei", "why": "These are SVE motor."}], "answer": 2}, {"id": "Q019", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "The chart labels XI with nucleus ambiguus and separately depicts a spinal accessory nucleus. Which interpretation is best?", "options": [{"text": "The two labels prove that XII and XI are identical", "why": "They are distinct motor systems."}, {"text": "Spinal XI originates in the retina", "why": "Retinal ganglion cells produce optic nerve axons."}, {"text": "The ambiguus label reflects traditional cranial-accessory terminology, distinct from spinal XI", "why": "Spinal XI supplying SCM/trapezius arises from upper cervical cord; cranial accessory functions are generally grouped with vagus."}, {"text": "All SCM motor neurons are in ambiguus", "why": "The spinal accessory nucleus is their principal origin."}, {"text": "XI is the main taste nerve", "why": "Taste mainly uses VII/IX/X."}], "answer": 2}, {"id": "Q020", "ref": "slide-5", "page": 5, "topic": "Nuclei chart", "stem": "Motor and sensory nuclear territories are separated developmentally by which landmark?", "options": [{"text": "Sulcus limitans", "why": "Motor derivatives are generally medial and sensory derivatives lateral to it."}, {"text": "Optic chiasm", "why": "This is a visual crossing."}, {"text": "Anterior median fissure", "why": "This is a ventral midline groove rather than the functional boundary."}, {"text": "Ciliary ganglion", "why": "This is a peripheral parasympathetic relay."}, {"text": "Foramen ovale", "why": "This transmits V3 through skull."}], "answer": 0}, {"id": "Q021", "ref": "slide-6", "page": 6, "topic": "Localization method", "stem": "A patient has a new ipsilateral III palsy and opposite limb weakness. Which brainstem level should be considered first?", "options": [{"text": "Cerebellar cortex alone", "why": "This does not contain the III motor fascicle."}, {"text": "Midbrain", "why": "III fascicles/nucleus localize the cranial component there."}, {"text": "Sacral spinal cord", "why": "This cannot contain III structures."}, {"text": "Medulla", "why": "This is more associated with IX/X/XII."}, {"text": "Caudal pons", "why": "This is more associated with VI/VII/VIII."}], "answer": 1}, {"id": "Q022", "ref": "slide-6", "page": 6, "topic": "Localization method", "stem": "Loss of body vibration and conscious position sense implicates which ascending brainstem tract?", "options": [{"text": "Medial lemniscus", "why": "This carries dorsal-column-relayed modalities after sensory crossing."}, {"text": "Corticospinal tract", "why": "This is descending motor."}, {"text": "Spinothalamic tract", "why": "This chiefly carries pain/temperature."}, {"text": "MLF as the principal body sensory tract", "why": "This coordinates ocular/vestibular systems."}, {"text": "Facial nerve fascicle", "why": "This is not the body's vibration/position pathway."}], "answer": 0}, {"id": "Q023", "ref": "slide-6", "page": 6, "topic": "Localization method", "stem": "What should follow identification of the cranial level and affected body tract in the lecture's approach?", "options": [{"text": "Determine medial versus lateral location, then match vascular territory", "why": "Structures should guide the artery/syndrome inference."}, {"text": "Ignore the side of each finding", "why": "Laterality is essential."}, {"text": "Assume every deficit is peripheral", "why": "Contralateral long-tract findings can indicate brainstem."}, {"text": "Name an artery without considering anatomy", "why": "An artery mnemonic alone can mislocalize the lesion."}, {"text": "Perform only a hearing test regardless of symptoms", "why": "The full pattern determines localization."}], "answer": 0}, {"id": "Q024", "ref": "slide-7", "page": 7, "topic": "Crossed patterns", "stem": "A patient has reduced pinprick on the right face and left body. Which paired lesion best explains the crossed pain-temperature pattern?", "options": [{"text": "One right peripheral facial motor branch", "why": "This does not explain opposite body sensation loss."}, {"text": "Right XII and medial lemniscus alone", "why": "These affect tongue motor and body position rather than pain-temperature."}, {"text": "Both optic nerves", "why": "These affect vision."}, {"text": "Left spinal V and left spinothalamic", "why": "This would reverse the classic sides."}, {"text": "Right spinal V system and right spinothalamic tract", "why": "Face fibers are ipsilateral before crossing there; body pain fibers already crossed in cord."}], "answer": 4}, {"id": "Q025", "ref": "slide-7", "page": 7, "topic": "Crossed patterns", "stem": "Why can a brainstem lesion produce an ipsilateral cranial motor deficit with contralateral limb weakness?", "options": [{"text": "Motor symptoms cannot be produced by brainstem disease", "why": "They are common localization clues."}, {"text": "It can injure a local cranial LMN fascicle and a corticospinal tract above its crossing", "why": "Nearby pathways have different laterality relative to their target muscles."}, {"text": "The same peripheral cranial nerve supplies opposite limbs", "why": "It does not."}, {"text": "All cranial nerves and corticospinal fibers cross at identical sites", "why": "They do not."}, {"text": "Corticospinal fibers are sensory", "why": "They are motor."}], "answer": 1}, {"id": "Q026", "ref": "slide-7", "page": 7, "topic": "Crossed patterns", "stem": "Which finding is least explained by an isolated peripheral CN XII nerve lesion?", "options": [{"text": "Ipsilateral tongue weakness", "why": "This fits XII injury."}, {"text": "Ipsilateral tongue wasting", "why": "This can follow XII denervation."}, {"text": "Ipsilateral tongue fasciculations", "why": "These are possible LMN signs."}, {"text": "Tongue deviation toward the weak side", "why": "This fits a XII LMN lesion."}, {"text": "Contralateral body vibration and motor deficits", "why": "Those require additional CNS long-tract involvement rather than XII alone."}], "answer": 4}, {"id": "Q027", "ref": "slide-8", "page": 8, "topic": "Medial versus lateral", "stem": "Which combination most strongly suggests a medial brainstem lesion?", "options": [{"text": "Only anterior tongue taste loss after ear surgery", "why": "This can be peripheral chorda tympani injury."}, {"text": "Only shoulder droop after neck biopsy", "why": "This can be peripheral XI injury."}, {"text": "Corticospinal weakness with medial lemniscal sensory loss", "why": "Both are classic medial long-tract structures."}, {"text": "Crossed pain-temperature loss with ipsilateral Horner and ataxia", "why": "This favors a lateral pattern."}, {"text": "Isolated ear fullness and fluctuating hearing", "why": "This can reflect inner-ear disease."}], "answer": 2}, {"id": "Q028", "ref": "slide-8", "page": 8, "topic": "Medial versus lateral", "stem": "Which tract near the midline coordinates conjugate ocular and vestibular movements?", "options": [{"text": "Spinothalamic", "why": "This chiefly carries body pain/temperature."}, {"text": "MLF", "why": "The medial longitudinal fasciculus links ocular motor/vestibular circuitry."}, {"text": "Inferior cerebellar peduncle exclusively", "why": "This is a cerebellar connection, not the named internuclear gaze tract."}, {"text": "Spinal trigeminal tract", "why": "This carries ipsilateral face sensory fibers before relay."}, {"text": "Pyramid exclusively", "why": "This is the major descending voluntary motor tract."}], "answer": 1}, {"id": "Q029", "ref": "slide-8", "page": 8, "topic": "Medial versus lateral", "stem": "Which group is most characteristic of lateral brainstem involvement?", "options": [{"text": "Only optic nerve and olfactory bulb", "why": "These are forebrain-associated pathways."}, {"text": "Spinal V, spinothalamic, cerebellar connections, descending sympathetics", "why": "These explain crossed pain-temperature, ataxia, and Horner signs."}, {"text": "Only peripheral VII terminal branches", "why": "These do not account for long-tract/autonomic brainstem signs."}, {"text": "Only the ciliary ganglion", "why": "This is a peripheral ocular parasympathetic relay."}, {"text": "Only XII, pyramid, and medial lemniscus", "why": "This is the classic medial medullary group."}], "answer": 1}, {"id": "Q030", "ref": "slide-9", "page": 9, "topic": "Horner syndrome", "stem": "Which pupil finding is expected from loss of sympathetic iris dilator function?", "options": [{"text": "Loss of vision from retinal ganglion destruction as the defining sign", "why": "Horner is an autonomic rather than primary visual afferent syndrome."}, {"text": "Mydriasis from loss of constrictor function", "why": "That reflects parasympathetic dysfunction rather than the sympathetic lesion."}, {"text": "Miosis", "why": "The affected pupil becomes smaller because dilation is impaired."}, {"text": "Obligatory bilateral fixed dilation", "why": "This is not the typical unilateral Horner pattern."}, {"text": "No possible pupil change", "why": "Sympathetic output contributes to pupil size."}], "answer": 2}, {"id": "Q031", "ref": "slide-9", "page": 9, "topic": "Horner syndrome", "stem": "Mild ptosis in Horner syndrome results primarily from denervation of which muscle?", "options": [{"text": "Orbicularis oculi", "why": "This closes the eyelid through VII."}, {"text": "Superior oblique", "why": "This moves the globe through IV."}, {"text": "Lateral rectus", "why": "This abducts the globe through VI."}, {"text": "Superior tarsal muscle", "why": "Its sympathetic smooth-muscle contribution to lid elevation is lost."}, {"text": "Levator palpebrae superioris", "why": "This skeletal muscle receives III and causes more marked ptosis when paralyzed."}], "answer": 3}, {"id": "Q032", "ref": "slide-9", "page": 9, "topic": "Horner syndrome", "stem": "A left lateral medullary lesion interrupts descending hypothalamospinal fibers. Which autonomic finding is predicted?", "options": [{"text": "Only contralateral parotid secretion loss", "why": "This is not the descending sympathetic pattern."}, {"text": "Bilateral tongue fasciculations as its autonomic sign", "why": "These are motor denervation findings."}, {"text": "Left Horner syndrome", "why": "These sympathetic fibers descend ipsilaterally in lateral brainstem."}, {"text": "Left fixed dilated pupil as the typical sympathetic sign", "why": "Horner causes miosis, not the III-type mydriasis."}, {"text": "Right Horner as the obligatory pattern", "why": "The classic central sympathetic deficit is ipsilateral."}], "answer": 2}, {"id": "Q033", "ref": "slide-9", "page": 9, "topic": "Horner syndrome", "stem": "Which comparison distinguishes Horner syndrome from a typical complete III palsy?", "options": [{"text": "III palsy cannot affect pupils", "why": "It carries pupilloconstrictor fibers."}, {"text": "Both syndromes necessarily imply a medial medullary lesion", "why": "They have multiple possible sites and mechanisms."}, {"text": "Both always have identical down-and-out eyes", "why": "Horner does not inherently paralyze III eye muscles."}, {"text": "Horner is caused only by facial motor loss", "why": "VII motor loss affects eyelid closure rather than iris dilation."}, {"text": "Horner has miosis/mild ptosis; complete III can have mydriasis/marked ptosis and ophthalmoplegia", "why": "Sympathetic versus ocular somatic/parasympathetic pathways differ."}], "answer": 4}, {"id": "Q034", "ref": "slide-9", "page": 9, "topic": "Horner syndrome", "stem": "Anhidrosis in Horner syndrome reflects loss of which function?", "options": [{"text": "Sympathetic stimulation of sweat glands", "why": "Sweating depends on sympathetic output, with distribution varying by lesion location."}, {"text": "Somatic motor input to levator", "why": "This controls lid elevation."}, {"text": "Parasympathetic sphincter pupillae activity", "why": "This controls constriction, not sweating."}, {"text": "Cochlear afferent transmission", "why": "This is hearing."}, {"text": "Taste input to solitary nucleus", "why": "This is sensory."}], "answer": 0}, {"id": "Q035", "ref": "slide-10", "page": 10, "topic": "Medial medulla anatomy", "stem": "Which three structures define the lecture's medial medullary localization model?", "options": [{"text": "Pyramid, medial lemniscus, XII fascicle", "why": "They predict motor, position/vibration, and tongue deficits."}, {"text": "Optic chiasm and pituitary", "why": "These are not medullary structures."}, {"text": "Facial nucleus, cochlear structures, middle cerebellar peduncle", "why": "These favor lateral pons."}, {"text": "Ambiguus, spinal V, inferior cerebellar peduncle", "why": "These are key lateral medullary structures."}, {"text": "III fascicle and red nucleus alone", "why": "These are midbrain structures."}], "answer": 0}, {"id": "Q036", "ref": "slide-10", "page": 10, "topic": "Medial medulla anatomy", "stem": "A right medullary XII fascicle injury causes which tongue finding?", "options": [{"text": "Only loss of anterior tongue taste", "why": "Taste is VII, not XII."}, {"text": "Leftward protrusion from right LMN weakness", "why": "This reverses the classic direction."}, {"text": "Only jaw deviation right", "why": "This is a V3 motor finding."}, {"text": "Only uvular deviation right", "why": "This primarily reflects palatal/vagal weakness."}, {"text": "Rightward protrusion with right LMN weakness", "why": "The tongue points toward the weak genioglossus in a XII LMN lesion."}], "answer": 4}, {"id": "Q037", "ref": "slide-10", "page": 10, "topic": "Medial medulla anatomy", "stem": "A left medial lemniscus lesion above the sensory decussation causes what?", "options": [{"text": "Right body vibration and position loss", "why": "The body sensory pathway has crossed in caudal medulla."}, {"text": "Left facial pain-temperature loss as its primary effect", "why": "This implicates spinal V rather than medial lemniscus."}, {"text": "Left tongue wasting as its direct effect", "why": "This implicates XII."}, {"text": "Only right hearing loss", "why": "This is auditory circuitry."}, {"text": "No sensory effect because it is motor", "why": "Medial lemniscus is sensory."}], "answer": 0}, {"id": "Q038", "ref": "slide-11", "page": 11, "topic": "Medial medullary syndrome", "stem": "A 66-year-old suddenly develops left-sided limb weakness and difficulty identifying passive movement of his left toes. His tongue deviates right on protrusion and has right-sided weakness. Facial pain-temperature sensation and hearing are intact. Examination suggests interruption of motor and position-sense pathways on one side of the medulla together with an ipsilateral cranial motor fascicle. Which localization best accounts for the combination?", "options": [{"text": "Left lateral pons", "why": "This favors VII/VIII and pain-temperature rather than XII/position."}, {"text": "Right lateral medulla", "why": "This favors bulbar/crossed pain-temperature and ataxic findings."}, {"text": "Left medial medulla", "why": "This would reverse the tongue and body sides."}, {"text": "Right peripheral XII alone", "why": "This cannot explain opposite limb weakness and position loss."}, {"text": "Right medial medulla", "why": "Right XII plus right pyramid/medial lemniscus yields right tongue and left body deficits."}], "answer": 4}, {"id": "Q039", "ref": "slide-11", "page": 11, "topic": "Medial medullary syndrome", "stem": "Which artery group is classically associated with medial medullary/Dejerine syndrome?", "options": [{"text": "AICA only", "why": "This classically supplies lateral pontine territories."}, {"text": "ACOM only", "why": "This is an anterior circulation connection."}, {"text": "MCA only", "why": "This mainly supplies lateral cerebral territories."}, {"text": "Middle meningeal artery", "why": "This chiefly supplies dura."}, {"text": "ASA or paramedian vertebral branches", "why": "These supply the medial medullary territory."}], "answer": 4}, {"id": "Q040", "ref": "slide-11", "page": 11, "topic": "Medial medullary syndrome", "stem": "Which deficit is produced by pyramid involvement in a right medial medullary lesion above decussation?", "options": [{"text": "Left limb weakness", "why": "The corticospinal fibers will cross caudally."}, {"text": "Right isolated pupil dilation", "why": "This is not a direct pyramid effect."}, {"text": "Right facial paralysis as the primary effect", "why": "Facial motor nucleus/fascicles are pontine."}, {"text": "Left hearing loss only", "why": "This is VIII/auditory circuitry."}, {"text": "Right limb pain loss only", "why": "Pain is spinothalamic and has a different localization."}], "answer": 0}, {"id": "Q041", "ref": "slide-11", "page": 11, "topic": "Medial medullary syndrome", "stem": "Which finding would favor classic medial medullary over lateral medullary syndrome?", "options": [{"text": "Hoarseness and dysphagia from ambiguus", "why": "These favor lateral medulla."}, {"text": "Ipsilateral XII weakness with opposite body vibration loss", "why": "XII and medial lemniscus are key medial structures."}, {"text": "Prominent vestibular vertigo as the only clue", "why": "This is more characteristic of lateral vestibular involvement."}, {"text": "Ipsilateral Horner with crossed pain-temperature", "why": "This favors lateral involvement."}, {"text": "Inferior cerebellar peduncle ataxia alone", "why": "This favors lateral medulla."}], "answer": 1}, {"id": "Q042", "ref": "slide-12", "page": 12, "topic": "Lateral medulla anatomy", "stem": "Which structure best explains hoarseness and dysphagia in a lateral medullary lesion?", "options": [{"text": "Nucleus ambiguus", "why": "Its IX/X branchial motor output supports pharyngeal/laryngeal function."}, {"text": "Pyramid", "why": "This carries descending motor commands to body."}, {"text": "Medial lemniscus", "why": "This carries body position/vibration."}, {"text": "Oculomotor nucleus", "why": "This is midbrain ocular motor circuitry."}, {"text": "Hypoglossal fascicle alone", "why": "This supplies tongue rather than most palate/larynx motor output."}], "answer": 0}, {"id": "Q043", "ref": "slide-12", "page": 12, "topic": "Lateral medulla anatomy", "stem": "Damage to the left spinal trigeminal tract/nucleus in the medulla most directly causes what?", "options": [{"text": "Right body vibration loss", "why": "This is a medial lemniscal effect."}, {"text": "Bilateral hearing loss as the obligatory finding", "why": "This is not the primary spinal V modality."}, {"text": "Left tongue wasting", "why": "This is XII motor injury."}, {"text": "Right facial-expression paralysis", "why": "This is a right VII motor deficit."}, {"text": "Left facial pain-temperature loss", "why": "These facial afferents are ipsilateral before the relevant central crossing."}], "answer": 4}, {"id": "Q044", "ref": "slide-12", "page": 12, "topic": "Lateral medulla anatomy", "stem": "Injury to the inferior cerebellar peduncle in a left lateral medullary lesion most characteristically causes what?", "options": [{"text": "Only anterior tongue taste loss", "why": "This is a VII sensory branch problem."}, {"text": "Right tongue fasciculations", "why": "This implicates right XII LMN output."}, {"text": "Left limb/gait ataxia", "why": "Disrupted ipsilateral cerebellar connections impair coordination."}, {"text": "Pure right limb paralysis from a corticospinal lesion", "why": "This implicates the pyramid rather than the peduncle."}, {"text": "Left monocular blindness", "why": "This implicates prechiasmal visual pathways."}], "answer": 2}, {"id": "Q045", "ref": "slide-12", "page": 12, "topic": "Lateral medulla anatomy", "stem": "Which structure explains vertigo and nystagmus in the lateral medullary model?", "options": [{"text": "Vestibular nuclei/connections", "why": "They mediate head-motion and gaze-stabilization signals."}, {"text": "Inferior salivatory nucleus alone", "why": "This supplies parotid parasympathetic output."}, {"text": "Pyramid alone", "why": "This explains limb motor weakness, not the vestibular pattern."}, {"text": "Gracile nucleus alone", "why": "This relays lower-body vibration/position."}, {"text": "XII fascicle alone", "why": "This supplies tongue muscles."}], "answer": 0}, {"id": "Q046", "ref": "slide-12", "page": 12, "topic": "Lateral medulla anatomy", "stem": "A right spinothalamic lesion in the medulla causes which deficit?", "options": [{"text": "Only right hearing loss", "why": "This is auditory, not spinothalamic."}, {"text": "Right facial vibration loss only", "why": "This is a different sensory system."}, {"text": "Left tongue weakness", "why": "This implicates left XII motor output."}, {"text": "Left body pain-temperature loss", "why": "These body afferents already crossed near spinal entry."}, {"text": "Right body position loss only", "why": "This implicates medial lemniscus at that level."}], "answer": 3}, {"id": "Q047", "ref": "slide-13", "page": 13, "topic": "Wallenberg syndrome", "stem": "A 70-year-old man abruptly develops severe vertigo, vomiting, a hoarse voice, and difficulty swallowing. Examination reveals left limb ataxia, left miosis with mild ptosis, reduced pinprick on the left face, and reduced pinprick on the right trunk and limbs. Limb strength and vibration sense are relatively preserved. Which region best unifies the crossed sensory, bulbar, vestibular, and sympathetic findings?", "options": [{"text": "Right peripheral vagus nerve alone", "why": "This cannot explain crossed body sensation, ataxia, and Horner."}, {"text": "Left ventromedial midbrain", "why": "This favors III palsy plus opposite motor weakness."}, {"text": "Left lateral medulla", "why": "Ambiguus, spinal V, spinothalamic, cerebellar/vestibular, and sympathetic involvement fits Wallenberg."}, {"text": "Right medial medulla", "why": "This favors right XII with left motor/position deficits."}, {"text": "Left medial pons", "why": "This favors VI with opposite motor/position loss."}], "answer": 2}, {"id": "Q048", "ref": "slide-13", "page": 13, "topic": "Wallenberg syndrome", "stem": "Which vascular territory is most characteristic of Wallenberg syndrome?", "options": [{"text": "MCA as the main medullary artery", "why": "MCA supplies cerebral territories."}, {"text": "External carotid facial artery", "why": "This does not supply the main medullary territory."}, {"text": "PCA as the only classic territory", "why": "This is more associated with midbrain/cerebral posterior circulation."}, {"text": "AICA as the only classic territory", "why": "This is more associated with lateral pons."}, {"text": "PICA or vertebral artery", "why": "Both commonly supply the dorsolateral medullary region."}], "answer": 4}, {"id": "Q049", "ref": "slide-13", "page": 13, "topic": "Wallenberg syndrome", "stem": "Which structure-deficit pairing is correct in lateral medulla?", "options": [{"text": "Inferior cerebellar peduncle — contralateral tongue wasting", "why": "It mediates cerebellar coordination, not XII denervation."}, {"text": "Spinal V — contralateral body vibration loss", "why": "Spinal V chiefly carries ipsilateral facial pain-temperature here."}, {"text": "Descending sympathetics — ipsilateral Horner", "why": "The central sympathetic pathway descends ipsilaterally."}, {"text": "Vestibular nuclei — isolated hand paralysis", "why": "Vestibular injury causes balance/gaze symptoms rather than pure limb force loss."}, {"text": "Ambiguus — isolated eye abduction failure", "why": "Ambiguus supplies pharyngeal/laryngeal motor output."}], "answer": 2}, {"id": "Q050", "ref": "slide-13", "page": 13, "topic": "Wallenberg syndrome", "stem": "Why can substantial swallowing difficulty coexist with relatively preserved limb strength in classic Wallenberg syndrome?", "options": [{"text": "All cranial motor output bypasses the brainstem", "why": "It does not."}, {"text": "Dysphagia proves the lesion is cortical in every case", "why": "A medullary motor nucleus lesion can cause it."}, {"text": "The corticospinal tract supplies only pharynx", "why": "It controls body motor pathways."}, {"text": "Ambiguus is lateral, whereas major corticospinal fibers are more medial", "why": "The syndrome need not interrupt the pyramid."}, {"text": "Ataxia is identical to paralysis", "why": "Coordination and strength are different functions."}], "answer": 3}, {"id": "Q051", "ref": "slide-13", "page": 13, "topic": "Wallenberg syndrome", "stem": "A patient has right lateral medullary ischemia. Which combined pain-temperature pattern is predicted?", "options": [{"text": "Right face and right body loss as the required pattern", "why": "The body tract carries opposite-side input."}, {"text": "Bilateral body vibration loss without face findings", "why": "This is not the classic lateral pain pattern."}, {"text": "Right face and left body loss", "why": "Ipsilateral spinal V and crossed-body spinothalamic pathways are injured."}, {"text": "Only the left eye loses vision", "why": "This is a visual rather than pain-temperature deficit."}, {"text": "Left face and right body loss", "why": "This would favor a left lateral lesion."}], "answer": 2}, {"id": "Q052", "ref": "slide-14", "page": 14, "topic": "Medial pons anatomy", "stem": "Which cranial fascicle joins corticospinal and medial lemniscal structures in the lecture's medial pontine model?", "options": [{"text": "Spinal XI roots", "why": "These arise in upper cervical cord."}, {"text": "CN VI", "why": "Its injury impairs ipsilateral lateral rectus/abduction."}, {"text": "CN XII", "why": "This is the medial medullary motor clue."}, {"text": "CN III", "why": "This is the medial midbrain clue."}, {"text": "CN VIII as the classic medial fascicle", "why": "VIII is more lateral pontomedullary sensory circuitry."}], "answer": 1}, {"id": "Q053", "ref": "slide-14", "page": 14, "topic": "Medial pons anatomy", "stem": "A left VI fascicle injury most directly causes which deficit?", "options": [{"text": "Bilateral loss of smell", "why": "This is forebrain-associated olfactory dysfunction."}, {"text": "Failure to adduct the left eye during right gaze with preserved abduction", "why": "This suggests left MLF dysfunction rather than VI fascicle."}, {"text": "Right tongue wasting", "why": "This is right XII LMN injury."}, {"text": "Failure to abduct the left eye", "why": "The fascicle carries motor output to left lateral rectus."}, {"text": "Left facial pain loss as its only direct function", "why": "VI is motor, not trigeminal sensory."}], "answer": 3}, {"id": "Q054", "ref": "slide-14", "page": 14, "topic": "Medial pons anatomy", "stem": "Why should VI fascicle injury be distinguished from VI nucleus injury?", "options": [{"text": "The nucleus also coordinates opposite-eye adduction through interneurons", "why": "A nuclear lesion can cause ipsilateral conjugate gaze palsy rather than only one eye's abduction deficit."}, {"text": "The nucleus is in the cerebral cortex", "why": "It is in caudal pons."}, {"text": "The fascicle directly supplies both eyes' lateral recti", "why": "One peripheral VI output supplies one lateral rectus."}, {"text": "The fascicle is sensory and nucleus is motor", "why": "Both are part of motor circuitry, but nuclear interneurons add coordination."}, {"text": "Neither can affect horizontal gaze", "why": "Both are central to horizontal motor function."}], "answer": 0}, {"id": "Q055", "ref": "slide-15", "page": 15, "topic": "Medial pontine syndrome", "stem": "A 64-year-old woman suddenly develops right arm and leg weakness. She also has reduced vibration and toe-position sensation on the right. Her left eye cannot abduct, producing horizontal diplopia when she looks left; the right eye adducts normally. There is no tongue wasting, hoarseness, or prominent hearing loss. Which localization best combines the cranial fascicle and long-tract deficits?", "options": [{"text": "Left medial medulla", "why": "This favors XII rather than VI."}, {"text": "Right medial pons", "why": "This would reverse the eye/body sides."}, {"text": "Left lateral medulla", "why": "This favors ambiguus and crossed pain-temperature, not this VI/position pattern."}, {"text": "Right facial canal", "why": "This cannot produce opposite limb motor/position loss."}, {"text": "Left medial pons", "why": "Left VI fascicle with left corticospinal/medial lemniscal pathways causes this crossed pattern."}], "answer": 4}, {"id": "Q056", "ref": "slide-15", "page": 15, "topic": "Medial pontine syndrome", "stem": "Which arterial branch group classically supplies the medial pontine territory in this lecture?", "options": [{"text": "Anterior communicating branches", "why": "These do not provide the main medial pontine supply."}, {"text": "Central retinal branches", "why": "These supply retina."}, {"text": "Paramedian basilar branches", "why": "These provide the relevant medial pontine supply."}, {"text": "PICA alone", "why": "This is strongly associated with lateral medulla."}, {"text": "Middle meningeal branches", "why": "These chiefly supply dura."}], "answer": 2}, {"id": "Q057", "ref": "slide-15", "page": 15, "topic": "Medial pontine syndrome", "stem": "Right medial pons injury involving VI fascicle, corticospinal tract, and medial lemniscus predicts which pattern?", "options": [{"text": "Only upgaze palsy and light-near dissociation", "why": "This favors dorsal midbrain."}, {"text": "Right abduction weakness with left limb motor and position deficits", "why": "The cranial motor output is ipsilateral and the long tracts represent opposite body."}, {"text": "Right tongue deviation with left position loss as the specific VI pattern", "why": "Tongue deviation is a XII clue to medulla."}, {"text": "Left abduction weakness with right body deficits", "why": "This fits a left medial pontine lesion."}, {"text": "Right facial paralysis with right hearing loss alone", "why": "This favors lateral pontine VII/VIII structures."}], "answer": 1}, {"id": "Q058", "ref": "slide-15", "page": 15, "topic": "Medial pontine syndrome", "stem": "Which preserved modality is compatible with the lecture's selective medial pontine model?", "options": [{"text": "All limb force necessarily", "why": "Corticospinal involvement impairs force."}, {"text": "Body vibration necessarily", "why": "Medial lemniscal involvement impairs it."}, {"text": "All sensory modalities must be abolished", "why": "Selective tract involvement can dissociate sensory findings."}, {"text": "Eye abduction on the fascicle-injured side necessarily", "why": "VI involvement impairs it."}, {"text": "Body pain-temperature", "why": "The lateral spinothalamic pathway may be spared while medial motor/position tracts are injured."}], "answer": 4}, {"id": "Q059", "ref": "slide-16", "page": 16, "topic": "Lateral pons anatomy", "stem": "Which cranial structures are key level clues for lateral pons?", "options": [{"text": "Spinal accessory nucleus in cervical cord only", "why": "This is not the defining lateral pontine pair."}, {"text": "VII facial and VIII vestibulocochlear structures", "why": "Their combination favors pontine/pontomedullary localization."}, {"text": "Only olfactory bulb and optic chiasm", "why": "These are forebrain-associated."}, {"text": "XII and pyramid alone", "why": "These favor medial medulla."}, {"text": "III and red nucleus", "why": "These are midbrain clues."}], "answer": 1}, {"id": "Q060", "ref": "slide-16", "page": 16, "topic": "Lateral pons anatomy", "stem": "Damage to the facial nucleus or fascicle causes which facial motor pattern?", "options": [{"text": "Ipsilateral upper and lower facial weakness", "why": "This is an LMN pattern even when the lesion is inside pons."}, {"text": "Only tongue deviation", "why": "This is XII dysfunction."}, {"text": "Only contralateral lower-face weakness with forehead sparing", "why": "This is the classic supranuclear pattern."}, {"text": "Only loss of face pain-temperature", "why": "This is spinal V sensory dysfunction."}, {"text": "Only hearing loss", "why": "This is VIII/auditory dysfunction."}], "answer": 0}, {"id": "Q061", "ref": "slide-16", "page": 16, "topic": "Lateral pons anatomy", "stem": "Which lateral pontine pathway explains contralateral body pain-temperature loss?", "options": [{"text": "Corticobulbar as a sensory pathway", "why": "This is descending motor output."}, {"text": "Facial motor fascicle", "why": "This controls ipsilateral facial muscles."}, {"text": "Spinothalamic tract", "why": "It already crossed in the spinal cord."}, {"text": "Cochlear nucleus", "why": "This processes hearing."}, {"text": "Medial lemniscus as the main pain pathway", "why": "This carries position/vibration and fine touch."}], "answer": 2}, {"id": "Q062", "ref": "slide-16", "page": 16, "topic": "Lateral pons anatomy", "stem": "Which lateral pontine involvement best explains ipsilateral hearing loss?", "options": [{"text": "Vestibular nuclei alone", "why": "These chiefly explain vertigo/nystagmus."}, {"text": "XII nucleus", "why": "This supplies tongue skeletal motor output."}, {"text": "Cochlear nuclei or related VIII pathway", "why": "These are auditory structures."}, {"text": "Medial lemniscus", "why": "This carries body discriminative sensation rather than hearing."}, {"text": "Inferior salivatory nucleus alone", "why": "This is parotid parasympathetic output."}], "answer": 2}, {"id": "Q063", "ref": "slide-16", "page": 16, "topic": "Lateral pons anatomy", "stem": "Which cerebellar connections are highlighted in the lateral pontine model?", "options": [{"text": "Only the ciliary ganglion", "why": "This is an ocular parasympathetic relay."}, {"text": "Only the pyramidal decussation", "why": "This is a caudal medullary motor crossing."}, {"text": "Middle and inferior cerebellar peduncles", "why": "Their injury can produce ipsilateral ataxia."}, {"text": "Dorsal roots of the lumbar cord only", "why": "These are not the local pontine cerebellar connections."}, {"text": "Optic nerve and chiasm", "why": "These are visual pathways."}], "answer": 2}, {"id": "Q064", "ref": "slide-17", "page": 17, "topic": "Lateral pontine syndrome", "stem": "A 58-year-old develops abrupt vertigo, vomiting, and unsteadiness. Examination reveals weakness of the entire right face, right sensorineural hearing loss, right facial pinprick loss, and left body pinprick loss. There is right limb ataxia and mild right miosis with ptosis. Palatal elevation is relatively preserved. Which localization best explains the combination of facial motor, auditory, crossed sensory, and cerebellar findings?", "options": [{"text": "Dorsal midbrain", "why": "This favors vertical gaze and pupillary dissociation findings."}, {"text": "Right medial medulla", "why": "This would favor XII with opposite motor/position deficits."}, {"text": "Isolated right peripheral VII nerve", "why": "This cannot explain crossed body sensation and local VIII/cerebellar deficits."}, {"text": "Right lateral pons", "why": "VII/VIII and lateral sensory/autonomic/cerebellar structures fit an AICA-type pattern."}, {"text": "Left lateral pons", "why": "This would reverse the ipsilateral cranial and body sensory sides."}], "answer": 3}, {"id": "Q065", "ref": "slide-17", "page": 17, "topic": "Lateral pontine syndrome", "stem": "Which artery is the classic association for the lecture's lateral pontine syndrome?", "options": [{"text": "MCA", "why": "This mainly supplies cerebral territories."}, {"text": "PICA as the principal comparison", "why": "This is the classic lateral medullary association."}, {"text": "AICA", "why": "Anterior inferior cerebellar territory is the classic lateral pontine association."}, {"text": "ASA as the classic lateral pontine artery", "why": "This is strongly associated with spinal/medial medullary supply."}, {"text": "ACOM", "why": "This is an anterior cerebral connecting vessel."}], "answer": 2}, {"id": "Q066", "ref": "slide-17", "page": 17, "topic": "Lateral pontine syndrome", "stem": "A lateral pontine lesion causes facial paralysis despite preserved cortical facial input. Which structure accounts for it?", "options": [{"text": "Cochlear nucleus alone", "why": "This processes hearing."}, {"text": "Only contralateral motor cortex", "why": "The problem described is at the local pontine LMN level."}, {"text": "Facial nucleus/fascicle", "why": "This is the local lower motor pathway to ipsilateral face."}, {"text": "Spinal V sensory nucleus alone", "why": "This affects sensation, not facial-expression motor output."}, {"text": "Solitary nucleus alone", "why": "This processes taste/visceral afferents."}], "answer": 2}, {"id": "Q067", "ref": "slide-17", "page": 17, "topic": "Lateral pontine syndrome", "stem": "Which lateral pontine sign is attributed to descending sympathetic interruption?", "options": [{"text": "Bilateral loss of near accommodation necessarily", "why": "This is parasympathetic ocular circuitry."}, {"text": "Only an extensor plantar response", "why": "This is a corticospinal/UMN sign rather than sympathetic dysfunction."}, {"text": "Ipsilateral tongue wasting as the autonomic sign", "why": "This is XII LMN motor injury."}, {"text": "Ipsilateral Horner syndrome", "why": "The sympathetic pathway descends on that side."}, {"text": "Contralateral complete III palsy", "why": "III lies in midbrain and has a different output pattern."}], "answer": 3}, {"id": "Q068", "ref": "slide-17", "page": 17, "topic": "Lateral pontine syndrome", "stem": "Which structure-deficit pairing is correct?", "options": [{"text": "Spinal V — contralateral limb paralysis", "why": "This is face sensory circuitry, not corticospinal output."}, {"text": "Cerebellar peduncle — isolated pupil dilation", "why": "Peduncle damage chiefly affects coordination."}, {"text": "Facial nucleus — body vibration loss", "why": "This is medial lemniscal sensation rather than VII motor."}, {"text": "Vestibular nuclei — vertigo and nystagmus", "why": "These structures process balance and gaze-stabilization signals."}, {"text": "Cochlear pathway — tongue deviation", "why": "This is XII motor function."}], "answer": 3}, {"id": "Q069", "ref": "slide-17", "page": 17, "topic": "Lateral pontine syndrome", "stem": "Why are ipsilateral facial paralysis and hearing loss particularly helpful together in lateral brainstem localization?", "options": [{"text": "They prove every lesion is outside CNS", "why": "Pontine nuclei/fascicles can produce them."}, {"text": "They are the classic defining XII pair in medulla", "why": "XII supplies tongue."}, {"text": "They implicate adjacent VII/VIII-region structures in pons", "why": "This combination is more specific to level than vertigo alone."}, {"text": "They establish an AICA occlusion with certainty in every patient", "why": "The classic territory is a guide, but imaging and lesion extent still matter."}, {"text": "They require a single trigeminal branch lesion", "why": "V branches do not supply facial-expression motor or hearing."}], "answer": 2}, {"id": "Q070", "ref": "slide-18", "page": 18, "topic": "Pons versus medulla", "stem": "Which finding most strongly favors lateral medulla over the lecture's classic lateral pons pattern?", "options": [{"text": "Ipsilateral ataxia alone", "why": "This can occur in both."}, {"text": "Entire ipsilateral facial paralysis with hearing loss", "why": "This favors lateral pons."}, {"text": "Prominent dysphagia and hoarseness from ambiguus involvement", "why": "This is a key medullary level clue."}, {"text": "Vertigo alone", "why": "Vestibular involvement can occur in both."}, {"text": "Crossed face/body pain-temperature loss alone", "why": "This can occur at either lateral level."}], "answer": 2}, {"id": "Q071", "ref": "slide-18", "page": 18, "topic": "Pons versus medulla", "stem": "Which combination is shared by classic lateral pontine and lateral medullary patterns?", "options": [{"text": "Obligatory XII tongue wasting", "why": "This favors medial medulla."}, {"text": "Ipsilateral face pain-temperature loss with contralateral body pain-temperature loss", "why": "Both can involve spinal V and spinothalamic pathways."}, {"text": "Only upgaze palsy with light-near dissociation", "why": "This favors dorsal midbrain."}, {"text": "Obligatory complete III palsy", "why": "This is a midbrain clue, not a defining shared lateral feature."}, {"text": "Only contralateral forehead-sparing facial weakness", "why": "That is a supranuclear pattern rather than the common lateral sensory finding."}], "answer": 1}, {"id": "Q072", "ref": "slide-18", "page": 18, "topic": "Pons versus medulla", "stem": "A patient has vertigo, ataxia, and crossed pain-temperature loss. Which additional finding most favors AICA/pons over PICA/medulla?", "options": [{"text": "Hoarseness with palatal weakness", "why": "This favors medullary ambiguus involvement."}, {"text": "Preserved hearing as a required proof", "why": "Hearing preservation does not by itself establish the territory."}, {"text": "Ipsilateral LMN facial weakness", "why": "VII involvement is a pontine discriminator."}, {"text": "Anhidrosis alone", "why": "Sympathetic pathways can be involved in either."}, {"text": "Nystagmus alone", "why": "Vestibular structures can be involved in either."}], "answer": 2}, {"id": "Q073", "ref": "slide-18", "page": 18, "topic": "Pons versus medulla", "stem": "How should the slide's statement that facial paralysis is absent in PICA/medulla patterns be used?", "options": [{"text": "As proof that ataxia never occurs in pons", "why": "Both patterns can affect coordination."}, {"text": "As proof that no patient with medullary disease can have any facial motor symptom", "why": "That is too absolute."}, {"text": "As a statement that PICA supplies the facial nerve in all cases", "why": "It does not define the classic VII pontine territory."}, {"text": "As a classic pattern guide rather than an absolute rule for every extended lesion", "why": "Actual infarcts can vary in extent and arterial anatomy."}, {"text": "As a reason to ignore cranial nerve findings", "why": "Those findings are essential."}], "answer": 3}, {"id": "Q074", "ref": "slide-19", "page": 19, "topic": "Medial midbrain anatomy", "stem": "Which two structures form the lecture's medial midbrain localization pair?", "options": [{"text": "III fascicles and cerebral peduncle/corticospinal fibers", "why": "They predict ipsilateral ocular palsy and opposite limb weakness."}, {"text": "XII fascicle and medial lemniscus alone", "why": "This favors medial medulla."}, {"text": "Spinal V and ambiguus only", "why": "This favors lateral medulla."}, {"text": "Optic chiasm and olfactory bulb", "why": "These are forebrain-associated structures."}, {"text": "VII fascicle and cochlear structures", "why": "This favors lateral pons."}], "answer": 0}, {"id": "Q075", "ref": "slide-19", "page": 19, "topic": "Medial midbrain anatomy", "stem": "A right III fascicle is injured in the midbrain. Which ocular pattern is expected from a sufficiently complete lesion?", "options": [{"text": "Right ptosis with impaired III movements and possible mydriasis", "why": "The local III output supplies ipsilateral ocular somatic/parasympathetic functions."}, {"text": "Only left eye abduction failure", "why": "This is left VI output."}, {"text": "Only left facial sensory loss", "why": "This is a different pathway."}, {"text": "Only right lower-face weakness with forehead sparing", "why": "This is a corticobulbar facial pattern."}, {"text": "Only right tongue atrophy", "why": "This is XII."}], "answer": 0}, {"id": "Q076", "ref": "slide-19", "page": 19, "topic": "Medial midbrain anatomy", "stem": "The section contains superior colliculus, cerebral aqueduct, and III fascicles. What level is indicated?", "options": [{"text": "Caudal pons", "why": "This contains VI/VII and facial colliculus."}, {"text": "Lumbar cord", "why": "This has no colliculi or III fascicles."}, {"text": "Open medulla", "why": "This is identified by fourth ventricle and inferior olive."}, {"text": "Closed caudal medulla", "why": "This contains central canal and major decussations."}, {"text": "Rostral midbrain", "why": "Superior colliculus and III are the key pair."}], "answer": 4}, {"id": "Q077", "ref": "slide-20", "page": 20, "topic": "Weber syndrome", "stem": "A 63-year-old develops left ptosis, a down-and-out left eye, and new right arm and leg weakness. His right lower face is weak, but forehead movement is relatively preserved. There is no dominant crossed pain-temperature loss, hearing loss, or hoarseness. MRI demonstrates an acute lesion involving III fascicles and nearby descending motor bundles at the superior-colliculus level. Which syndrome pattern best fits?", "options": [{"text": "Left medial pontine syndrome", "why": "This uses VI rather than III as the cranial motor clue."}, {"text": "Left Wallenberg syndrome", "why": "This favors lateral medullary bulbar/crossed sensory findings."}, {"text": "Parinaud syndrome alone", "why": "This is a dorsal vertical-gaze pattern rather than III plus hemiparesis."}, {"text": "Left Weber syndrome", "why": "Ventromedial midbrain injury combines left III with right corticospinal/corticobulbar deficits."}, {"text": "Right Weber syndrome", "why": "This would reverse the ocular/body sides."}], "answer": 3}, {"id": "Q078", "ref": "slide-20", "page": 20, "topic": "Weber syndrome", "stem": "Which structure explains contralateral lower facial weakness in Weber syndrome?", "options": [{"text": "Inferior salivatory nucleus", "why": "This is parasympathetic IX output."}, {"text": "Ipsilateral facial nucleus in the midbrain", "why": "The facial motor nucleus is pontine, not midbrain."}, {"text": "Corticobulbar fibers", "why": "Descending supranuclear facial motor input is affected in the cerebral peduncle region."}, {"text": "Spinal V nucleus alone", "why": "This is somatic sensory rather than facial-expression motor."}, {"text": "Vestibular nuclei alone", "why": "These process balance/gaze rather than lower-face voluntary motor output."}], "answer": 2}, {"id": "Q079", "ref": "slide-20", "page": 20, "topic": "Weber syndrome", "stem": "Which artery and location best match the lecture's Weber model?", "options": [{"text": "ACOM — dorsal cervical cord", "why": "This is not the relevant brainstem pairing."}, {"text": "AICA — lateral pons", "why": "This is the classic lateral pontine pairing."}, {"text": "ASA — medial medulla", "why": "This is the Dejerine association."}, {"text": "PICA — lateral medulla", "why": "This is the Wallenberg association."}, {"text": "PCA branches — ventromedial midbrain", "why": "This is the classic territory/location pairing."}], "answer": 4}, {"id": "Q080", "ref": "slide-20", "page": 20, "topic": "Weber syndrome", "stem": "The figure also labels a tegmental midbrain/Benedikt region. III palsy with prominent contralateral tremor or ataxia rather than a pure peduncular hemiparesis suggests added involvement of what?", "options": [{"text": "Only a lumbar dorsal root", "why": "This cannot explain a midbrain ocular motor sign."}, {"text": "Only the middle-ear ossicles", "why": "This affects sound conduction rather than III and limb coordination."}, {"text": "Red-nuclear/cerebellar tegmental pathways", "why": "These help distinguish a tegmental pattern from a predominantly ventral Weber motor lesion."}, {"text": "Only the XII peripheral nerve", "why": "This produces tongue weakness."}, {"text": "Only the parotid gland", "why": "This cannot account for crossed ocular/coordination findings."}], "answer": 2}, {"id": "Q081", "ref": "slide-21", "page": 21, "topic": "Parinaud syndrome", "stem": "A 19-year-old reports headache and difficulty looking upward. Examination shows impaired upgaze, abnormal convergence-retraction movements with attempted upgaze, and pupils that react poorly to light but constrict to a near target. Horizontal eye movements and limb strength are relatively preserved. Imaging reveals a pineal-region mass compressing tissue near the cerebral aqueduct. Which region is most directly implicated?", "options": [{"text": "Ventromedial midbrain peduncle alone", "why": "This favors III with contralateral motor weakness."}, {"text": "An isolated peripheral VII branch", "why": "This affects facial movement rather than vertical gaze/light-near circuitry."}, {"text": "Lateral pons", "why": "This favors VII/VIII and crossed lateral sensory signs."}, {"text": "Medial medulla", "why": "This favors XII and opposite motor/position loss."}, {"text": "Dorsal midbrain/pretectal region", "why": "This is the characteristic Parinaud localization."}], "answer": 4}, {"id": "Q082", "ref": "slide-21", "page": 21, "topic": "Parinaud syndrome", "stem": "Which pupil pattern is called light-near dissociation in the lecture?", "options": [{"text": "Only an afferent corneal blink deficit", "why": "This concerns V1/VII rather than pupil behavior."}, {"text": "A pupil that dilates only during swallowing", "why": "This is not the described phenomenon."}, {"text": "Equal normal brisk light and near responses", "why": "There is no dissociation."}, {"text": "Poor light constriction with preserved near constriction", "why": "This is a characteristic dorsal midbrain clue in the appropriate pattern."}, {"text": "No light or near response because all III efferents are severed", "why": "That is an efferent failure rather than this dissociation."}], "answer": 3}, {"id": "Q083", "ref": "slide-21", "page": 21, "topic": "Parinaud syndrome", "stem": "Which movement abnormality is especially characteristic of Parinaud syndrome?", "options": [{"text": "Isolated inability of one eye to abduct", "why": "This favors a VI output lesion."}, {"text": "Convergence-retraction movements on attempted upgaze", "why": "This is the characteristic dorsal midbrain ocular motor sign."}, {"text": "Tongue fasciculations", "why": "This is XII LMN dysfunction."}, {"text": "Entire ipsilateral facial paralysis", "why": "This is VII LMN dysfunction."}, {"text": "Isolated inability to depress one adducted eye", "why": "This favors IV weakness."}], "answer": 1}, {"id": "Q084", "ref": "slide-21", "page": 21, "topic": "Parinaud syndrome", "stem": "A pineal-region mass produces vertical gaze abnormalities. Why does this favor dorsal rather than ventral midbrain localization?", "options": [{"text": "All ocular movement deficits are necessarily peripheral nerves", "why": "Supranuclear circuits can produce gaze deficits."}, {"text": "Vertical gaze is controlled only by the lumbar cord", "why": "It uses midbrain/brainstem circuitry."}, {"text": "Pineal compression primarily destroys medullary XII roots", "why": "These are remote from the pineal region."}, {"text": "The pineal gland is inside the internal acoustic meatus", "why": "It is not."}, {"text": "The mass can compress tectal/pretectal gaze-related structures", "why": "Their anatomy fits the vertical gaze/pupil pattern."}], "answer": 4}, {"id": "Q085", "ref": "slide-21", "page": 21, "topic": "Parinaud syndrome", "stem": "Which feature most clearly distinguishes the lecture's Parinaud pattern from Weber syndrome?", "options": [{"text": "Both require complete bilateral facial paralysis", "why": "That is not a defining feature of either."}, {"text": "Upgaze palsy with light-near dissociation rather than III fascicle palsy plus opposite hemiparesis", "why": "Dorsal and ventral midbrain structures differ."}, {"text": "Parinaud is always a medullary stroke", "why": "It is a dorsal midbrain syndrome with several causes."}, {"text": "Weber never includes ocular findings", "why": "III palsy is central to Weber."}, {"text": "The two names always describe the identical lesion", "why": "Their characteristic localizations differ."}], "answer": 1}, {"id": "Q086", "ref": "slide-22", "page": 22, "topic": "Integrated localization", "stem": "A patient has right tongue LMN weakness, left limb weakness, and left vibration/position loss. Following the lecture's sequence, what is the strongest explanation?", "options": [{"text": "Right lateral medulla because every crossed pattern is lateral", "why": "Crossed findings also occur in medial syndromes."}, {"text": "Left lateral pons because weakness is present", "why": "The XII clue localizes medullary rather than VII/VIII pontine structures."}, {"text": "A pineal lesion because all cranial deficits are midbrain", "why": "The specific nerve matters."}, {"text": "Isolated right XII nerve because tongue is abnormal", "why": "That does not explain body long-tract findings."}, {"text": "Right medial medulla involving XII, pyramid, and medial lemniscus", "why": "Cranial level and body modalities converge on one medial region."}], "answer": 4}, {"id": "Q087", "ref": "slide-22", "page": 22, "topic": "Integrated localization", "stem": "Why should the syndrome name come after level, tract, side, and territory are considered?", "options": [{"text": "The name summarizes an anatomical explanation rather than replacing it", "why": "This supports localization when a pattern is incomplete or atypical."}, {"text": "Every patient must display every listed feature before localization is possible", "why": "Partial lesions can still be localized."}, {"text": "An artery name specifies all deficits with no exceptions", "why": "Vascular anatomy and lesion extent vary."}, {"text": "Cranial nerve findings carry no level information", "why": "They are central to the method."}, {"text": "A normal strength test excludes all brainstem disease", "why": "Lateral sensory/bulbar/vestibular lesions may spare strength."}], "answer": 0}, {"id": "Q088", "ref": "slide-22", "page": 22, "topic": "Integrated localization", "stem": "A patient has vertigo and ataxia without further examination. Which next information would most help distinguish the lecture's lateral pontine and medullary patterns?", "options": [{"text": "Ignore body sensory testing because ataxia is present", "why": "Crossed sensory patterns add useful localization evidence."}, {"text": "Check only whether one pupil is larger in bright sunlight", "why": "This alone does not establish the full lateral level."}, {"text": "Name Weber syndrome before examining the eyes", "why": "Weber requires a different ocular/motor pattern."}, {"text": "Assess facial motor/hearing and palate/voice/swallowing findings", "why": "VII/VIII versus ambiguus-related IX/X clues help identify level."}, {"text": "Assume vertigo alone proves PICA occlusion", "why": "Vestibular symptoms have multiple sites/causes."}], "answer": 3}]};
